const body = $input.first().json.body || $input.first().json;
const callbackId = body.callbackId || '';
if (callbackId) $execution.customData.set('callbackId', callbackId);

const co = body.campaignOptions || {};
const cr = body.creativeOptions || {};
const pl = co.placements || {};
const t = co.targeting || {};

const hasFb = (pl.facebook === true || pl.facebook === 'true') ? 1 : 0;
const hasIg = (pl.instagram === true || pl.instagram === 'true') ? 1 : 0;

const fbRaw = (co.fbPositions || []).filter(function(p){ return p !== 'reels'; });
const igRaw = (co.igPositions || []).filter(function(p){ return p !== 'reels' && p !== 'ig_search'; });
const fbPosStr = fbRaw.length ? fbRaw.join(',') : 'feed,story';
const igPosStr = igRaw.length ? igRaw.join(',') : 'stream,story';

const locs = t.locations || [];
let geoStr;
if (locs.length > 0) {
  const cities = locs.filter(function(l){ return l.type === 'city'; });
  const regions = locs.filter(function(l){ return l.type === 'region'; });
  const countries = locs.filter(function(l){ return l.type === 'country'; });
  const geoObj = {};
  if (cities.length) geoObj.cities = cities.map(function(l){ return { key: l.key }; });
  if (regions.length) geoObj.regions = regions.map(function(l){ return { key: l.key }; });
  if (countries.length) geoObj.countries = countries.map(function(l){ return l.key; });
  else if (!cities.length && !regions.length) geoObj.countries = ['BR'];
  geoStr = JSON.stringify(geoObj);
} else {
  geoStr = '{"countries":["BR"]}';
}

const ints = t.interests || [];
const interestsStr = ints.length
  ? JSON.stringify(ints.map(function(i){ return { id: i.id, name: i.name }; }))
  : '';

return [{
  json: {
    token: body.token || co.token || '',
    callbackId: callbackId,
    adAccountId: co.adAccountId || '',
    campaignName: co.name || '',
    objective: co.campaignType === 'sales' ? 'OUTCOME_SALES' : 'OUTCOME_ENGAGEMENT',
    dailyBudget: Math.round((co.dailyBudget || 0) * 100),
    pageId: co.pageId || '',
    whatsappNumber: (co.whatsappNumber || '').replace(/\D/g, ''),
    hasFacebook: hasFb,
    hasInstagram: hasIg,
    fbPositions: fbPosStr,
    igPositions: igPosStr,
    ageMin: t.ageMin || 18,
    ageMax: t.ageMax || 65,
    genderMode: t.genderMode || 'all',
    geoStr: geoStr,
    interestsStr: interestsStr,
    primaryText: cr.primaryText || '',
    headline: cr.headline || '',
    description: cr.description || '',
    mediaType: cr.mediaType || 'image',
    imageHash: cr.imageHash || null,
    videoId: cr.videoId || null,
    thumbnailUrl: cr.thumbnailUrl || null,
    whatsappMessage: cr.whatsappMessage || null
  }
}];

const fields = $('Extrair Campos').item.json;
const campaignId = $input.first().json.id;

const geo = JSON.parse(fields.geoStr);

const targeting = {
  geo_locations: geo,
  targeting_automation: { advantage_audience: 0 }
};

if (fields.ageMin > 18) targeting.age_min = fields.ageMin;
if (fields.ageMax < 65) targeting.age_max = fields.ageMax;

if (fields.genderMode === 'male') targeting.genders = [1];
else if (fields.genderMode === 'female') targeting.genders = [2];

if (fields.interestsStr) {
  const ints = JSON.parse(fields.interestsStr);
  if (ints.length) targeting.flexible_spec = [{ interests: ints }];
}

// hasFacebook e hasInstagram são 1 ou 0
const pubs = [];
if (fields.hasFacebook) pubs.push('facebook');
if (fields.hasInstagram) pubs.push('instagram');
if (pubs.length) targeting.publisher_platforms = pubs;

if (fields.hasFacebook) targeting.facebook_positions = fields.fbPositions.split(',');
if (fields.hasInstagram) targeting.instagram_positions = fields.igPositions.split(',');

const payload = {
  name: fields.campaignName,
  campaign_id: campaignId,
  billing_event: 'IMPRESSIONS',
  optimization_goal: 'CONVERSATIONS',
  destination_type: 'WHATSAPP',
  promoted_object: {
    page_id: fields.pageId,
    whatsapp_phone_number: fields.whatsappNumber
  },
  targeting: targeting,
  status: 'PAUSED',
  access_token: fields.token
};

return [{ json: { payloadStr: JSON.stringify(payload) } }];

const fields = $('Extrair Campos').item.json;
const adSetId = $input.first().json.id;
const waNumber = fields.whatsappNumber;
const waMsg = fields.whatsappMessage;
const waLink = waMsg
  ? 'https://wa.me/' + waNumber + '?text=' + encodeURIComponent(waMsg)
  : 'https://wa.me/' + waNumber;

const cta = { type: 'WHATSAPP_MESSAGE', value: { app_destination: 'WHATSAPP', whatsapp_number: waNumber } };

let objectStorySpec;
if (fields.mediaType === 'image') {
  objectStorySpec = {
    page_id: fields.pageId,
    link_data: {
      image_hash: fields.imageHash,
      message: fields.primaryText,
      name: fields.headline,
      link: waLink,
      call_to_action: cta
    }
  };
  if (fields.description) objectStorySpec.link_data.description = fields.description;
} else {
  objectStorySpec = {
    page_id: fields.pageId,
    video_data: {
      video_id: fields.videoId,
      message: fields.primaryText,
      title: fields.headline,
      call_to_action: cta
    }
  };
  if (fields.description) objectStorySpec.video_data.description = fields.description;
  if (fields.thumbnailUrl) objectStorySpec.video_data.image_url = fields.thumbnailUrl;
}

return [{ json: { adSetId, objectStorySpec: JSON.stringify(objectStorySpec), fields } }];
